//! Boolean `MOLT_*` runtime flags, read from the process environment once.
//!
//! [`RuntimeFlag`] is generated by `tools/gen_environment_registry.py` from
//! every `kind = "bool"` row of `src/molt/environment_registry.toml` that this
//! crate owns, so code cannot name a flag the registry does not know, and the
//! registry gate rejects a flag name spelled as a string in this crate. The
//! first [`enabled`] call scans the environment once and fixes every flag for
//! the life of the process; a flag is on only when its value is exactly `1`.
//! CPython reads its `PYTHON*` settings once at startup the same way. A hot
//! path (a generator resume, an awaitable check, a scheduler step) then tests
//! one bit where it used to call `getenv`, which takes the environment lock
//! and allocates a `String` (HF-230).

use std::ffi::OsString;
use std::sync::OnceLock;

pub(crate) use crate::runtime_flags_generated::RuntimeFlag;

const WORDS: usize = RuntimeFlag::ALL.len().div_ceil(64);

static FLAGS: OnceLock<[u64; WORDS]> = OnceLock::new();

/// Whether `flag` was exactly `1` in the process environment when the
/// runtime first asked about any flag.
#[inline]
pub(crate) fn enabled(flag: RuntimeFlag) -> bool {
    let (word, bit) = position(flag);
    FLAGS.get_or_init(|| read_flags(std::env::vars_os()))[word] & bit != 0
}

impl RuntimeFlag {
    /// The variable's name, as the registry spells it.
    pub(crate) const fn name(self) -> &'static str {
        Self::NAMES[self as usize]
    }

    fn from_name(name: &str) -> Option<Self> {
        Self::NAMES
            .binary_search(&name)
            .ok()
            .map(|index| Self::ALL[index])
    }
}

#[inline]
const fn position(flag: RuntimeFlag) -> (usize, u64) {
    let index = flag as usize;
    (index / 64, 1 << (index % 64))
}

/// The flag bits of one environment. The first entry for a name decides, as
/// `getenv` does when a name repeats.
fn read_flags(environment: impl IntoIterator<Item = (OsString, OsString)>) -> [u64; WORDS] {
    let mut seen = [0u64; WORDS];
    let mut bits = [0u64; WORDS];
    for (name, value) in environment {
        let Some(flag) = name.to_str().and_then(RuntimeFlag::from_name) else {
            continue;
        };
        let (word, bit) = position(flag);
        if seen[word] & bit != 0 {
            continue;
        }
        seen[word] |= bit;
        if value.to_str() == Some("1") {
            bits[word] |= bit;
        }
    }
    bits
}

#[cfg(test)]
mod tests {
    use super::*;

    fn environment(entries: &[(&str, &str)]) -> Vec<(OsString, OsString)> {
        entries
            .iter()
            .map(|(name, value)| (OsString::from(name), OsString::from(value)))
            .collect()
    }

    fn is_set(bits: &[u64; WORDS], flag: RuntimeFlag) -> bool {
        let (word, bit) = position(flag);
        bits[word] & bit != 0
    }

    #[test]
    fn names_are_sorted_unique_and_index_their_flags() {
        assert!(RuntimeFlag::NAMES.windows(2).all(|pair| pair[0] < pair[1]));
        for (index, flag) in RuntimeFlag::ALL.iter().copied().enumerate() {
            assert_eq!(flag as usize, index);
            assert!(flag.name().starts_with("MOLT_"));
            assert_eq!(RuntimeFlag::from_name(flag.name()), Some(flag));
        }
        assert_eq!(RuntimeFlag::from_name("MOLT_NOT_A_RUNTIME_FLAG"), None);
        assert_eq!(RuntimeFlag::from_name(""), None);
    }

    #[test]
    fn only_exactly_one_turns_a_flag_on() {
        let flag = RuntimeFlag::MOLT_TRACE_GENERATOR_STATE;
        assert!(is_set(
            &read_flags(environment(&[(flag.name(), "1")])),
            flag
        ));
        for value in ["", "0", "01", "1 ", "true", "yes", "on", "TRUE"] {
            let bits = read_flags(environment(&[(flag.name(), value)]));
            assert!(
                !is_set(&bits, flag),
                "{value:?} must not enable {}",
                flag.name()
            );
        }
    }

    #[test]
    fn the_first_entry_for_a_name_decides() {
        let flag = RuntimeFlag::MOLT_DEBUG_AWAITABLE;
        let first_on = read_flags(environment(&[(flag.name(), "1"), (flag.name(), "0")]));
        assert!(is_set(&first_on, flag));
        let first_off = read_flags(environment(&[(flag.name(), "0"), (flag.name(), "1")]));
        assert!(!is_set(&first_off, flag));
    }

    #[test]
    fn other_names_and_flags_stay_off() {
        let bits = read_flags(environment(&[
            ("MOLT_NOT_A_RUNTIME_FLAG", "1"),
            ("PATH", "1"),
            (RuntimeFlag::MOLT_PROFILE.name(), "1"),
        ]));
        for flag in RuntimeFlag::ALL {
            assert_eq!(is_set(&bits, flag), flag == RuntimeFlag::MOLT_PROFILE);
        }
    }
}
